import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.awt.event.*;import java.sql.*;import java.io.*;import java.util.*;
public class CampusEventApp extends JFrame {
 private final JTextField student=new JTextField(12),name=new JTextField(12);private final JComboBox<String> event=new JComboBox<>(new String[]{"Tech Fest","Cultural Night","Sports Meet"});
 private final JComboBox<String> filter=new JComboBox<>(new String[]{"All","Tech Fest","Cultural Night","Sports Meet"});
 private final DefaultTableModel model=new DefaultTableModel(new String[]{"Student ID","Name","Event"},0);private final JTable table=new JTable(model);private final RegistrationService service=new RegistrationService(new RegistrationDao());
 public CampusEventApp(){super("Campus Event Registration");setLayout(new BorderLayout(8,8));JMenuBar mb=new JMenuBar();JMenu file=new JMenu("File");JMenuItem refresh=new JMenuItem("Refresh"),export=new JMenuItem("Export CSV"),exit=new JMenuItem("Exit");file.add(refresh);file.add(export);file.addSeparator();file.add(exit);mb.add(file);setJMenuBar(mb);
 JPanel form=new JPanel(new FlowLayout(FlowLayout.LEFT));form.setBorder(BorderFactory.createTitledBorder("Student registration"));JButton register=new JButton("Register");form.add(new JLabel("Student ID"));form.add(student);form.add(new JLabel("Name"));form.add(name);form.add(event);form.add(register);
 JPanel tools=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton apply=new JButton("Filter");tools.add(new JLabel("Event"));tools.add(filter);tools.add(apply);
 JPanel north=new JPanel(new BorderLayout());north.add(form,BorderLayout.NORTH);north.add(tools,BorderLayout.SOUTH);add(north,BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);
 register.addActionListener(e->registerAsync());apply.addActionListener(e->loadAsync((String)filter.getSelectedItem()));refresh.addActionListener(e->loadAsync("All"));export.addActionListener(e->exportCsv());exit.addActionListener(e->dispose());setDefaultCloseOperation(DISPOSE_ON_CLOSE);setSize(850,460);setLocationRelativeTo(null);loadAsync("All");}
 private void registerAsync(){String id=student.getText().trim(),n=name.getText().trim(),ev=(String)event.getSelectedItem();if(!id.matches("[A-Za-z0-9-]{3,20}")||n.isBlank()){JOptionPane.showMessageDialog(this,"Enter a valid student ID and name.");return;}new SwingWorker<String,Void>(){protected String doInBackground()throws Exception{return service.register(id,n,ev);}protected void done(){try{JOptionPane.showMessageDialog(CampusEventApp.this,get());loadAsync("All");}catch(Exception ex){JOptionPane.showMessageDialog(CampusEventApp.this,ex.getCause()==null?ex.getMessage():ex.getCause().getMessage());}}}.execute();}
 private void loadAsync(String ev){new SwingWorker<java.util.List<String[]>,Void>(){protected java.util.List<String[]> doInBackground()throws Exception{return service.list(ev);}protected void done(){try{model.setRowCount(0);for(String[] r:get())model.addRow(r);}catch(Exception ex){JOptionPane.showMessageDialog(CampusEventApp.this,"Database unavailable: "+ex.getMessage());}}}.execute();}
 private void exportCsv(){JFileChooser fc=new JFileChooser();if(fc.showSaveDialog(this)==JFileChooser.APPROVE_OPTION){try(PrintWriter w=new PrintWriter(fc.getSelectedFile())){w.println("student_id,name,event");for(int i=0;i<model.getRowCount();i++)w.println(model.getValueAt(i,0)+","+model.getValueAt(i,1)+","+model.getValueAt(i,2));}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage());}}}
 public static void main(String[] a){SwingUtilities.invokeLater(()->new CampusEventApp().setVisible(true));}
}
class RegistrationService {private final RegistrationDao dao;RegistrationService(RegistrationDao d){dao=d;}String register(String id,String name,String event)throws Exception{if(id.isBlank()||name.isBlank())throw new IllegalArgumentException("Required fields are missing.");if(dao.exists(id,event))throw new IllegalArgumentException("Duplicate registration: this student is already registered for this event.");dao.insert(id,name,event);return "Registration saved.";}java.util.List<String[]> list(String event)throws Exception{return dao.list(event);}}
class RegistrationDao {
 private Connection connect()throws SQLException{String url=System.getenv().getOrDefault("DB_URL","jdbc:mysql://localhost:3306/campus_events");String user=System.getenv().getOrDefault("DB_USER","root"),pwd=System.getenv().getOrDefault("DB_PASSWORD","");return DriverManager.getConnection(url,user,pwd);}
 boolean exists(String id,String event)throws SQLException{try(Connection c=connect();PreparedStatement p=c.prepareStatement("SELECT 1 FROM registrations WHERE student_id=? AND event_name=?")){p.setString(1,id);p.setString(2,event);try(ResultSet r=p.executeQuery()){return r.next();}}}
 void insert(String id,String name,String event)throws SQLException{try(Connection c=connect();PreparedStatement p=c.prepareStatement("INSERT INTO registrations(student_id,student_name,event_name) VALUES(?,?,?)")){p.setString(1,id);p.setString(2,name);p.setString(3,event);p.executeUpdate();}}
 java.util.List<String[]> list(String event)throws SQLException{java.util.List<String[]> out=new ArrayList<>();String sql="All".equals(event)?"SELECT student_id,student_name,event_name FROM registrations ORDER BY id DESC LIMIT 100 OFFSET 0":"SELECT student_id,student_name,event_name FROM registrations WHERE event_name=? ORDER BY id DESC LIMIT 100 OFFSET 0";try(Connection c=connect();PreparedStatement p=c.prepareStatement(sql)){if(!"All".equals(event))p.setString(1,event);try(ResultSet r=p.executeQuery()){while(r.next())out.add(new String[]{r.getString(1),r.getString(2),r.getString(3)});}}return out;}
}
